entries[408160] = { ["name"] = "Schattenschlag", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion schlägt auf den Körper des Spielercharakters ein, während dieser körperlos ist, was dem Körper 238753 körperlichen Schaden zufügt und ihn auf den Spielercharakter zuschleudert. Der Spielercharakter vereinigt sich mit seinem Körper wieder und erleidet dessen fehlende Gesundheit als Schattenschaden. Der durch ' Schatten spalten ' erlittene Schaden wird 40 Sek. lang um 300% erhöht.\n\nWenn der Körper des Spielercharakters mit einem Segment von ' Entstellte Erde ' kollidiert, wird ' Zerschmettern ' ausgelöst." }
