entries[408218] = { ["name"] = "Schlängelnder Kriecherdrache: Blaue und silberne Rüstung", ["text"] = "Wirken in 3.5 sek. 3\nReagenzien:\nWildstoff (20), Makellose Protodrachenschuppe (10), Erweckte Ordnung (8), Fertiger Prototyp eines majestätischen Geschirrs , Felszahnleder (10)\nAngeln:\nDrakonisches Rezept in der Flasche\nTechnik:\nErhältlich im Auktionshaus\n\nSchlängelnder Kriecherdrache: Blaue und silberne Rüstung\nDrachenwächtermanuskript\nWird beim Aufheben gebunden\nBenutzen: Schaltet diese Anpassungsoption für den schlängelnden Kriecherdrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird.\n\"Eine Schriftrolle, die einen mächtigen Protodrachen mit leuchtend grünen Schuppen beschreibt.\"" }
entries[408219] = { ["name"] = "Konvergente Eruption", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Schattenflammenverschmelzung lässt schwarze Feuerbälle an Positionen in der Nähe niedergehen, die allen Spielercharakteren innerhalb von 5 Metern um die Einschlagsorte 167127 Schattenflammenschaden zufügen. Falls einer der Feuerbälle keinen Spielercharakter trifft, erleiden alle Spielercharaktere 238753 Schattenflammenschaden.\nKugeln der Dunkelheit bewegen sich dann auf den Einschlagsort zu und fügen Spielercharakteren in ihrer Bahn 382005 Schattenflammenschaden zu." }
entries[408220] = { ["name"] = "Schlängelnder Kriecherdrache: Gelbe und silberne Rüstung", ["text"] = "Wirken in 3.5 sek. 3\nReagenzien:\nWildstoff (20), Makellose Protodrachenschuppe (10), Erweckte Ordnung (8), Fertiger Prototyp eines Geschirrs des Forschers , Felszahnleder (10)\nAngeln:\nDrakonisches Rezept in der Flasche\nTechnik:\nErhältlich im Auktionshaus\n\nSchlängelnder Kriecherdrache: Gelbe und silberne Rüstung\nDrachenwächtermanuskript\nWird beim Aufheben gebunden\nBenutzen: Schaltet diese Anpassungsoption für den schlängelnden Kriecherdrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird.\n\"Eine Schriftrolle, die einen mächtigen Protodrachen mit leuchtend grünen Schuppen beschreibt.\"" }
entries[408221] = { ["name"] = "Schlängelnder Kriecherdrache: Weißes Haar", ["text"] = "Wirken in 3.5 sek. 3\nReagenzien:\nWildstoff (15), Glitzerndes Pergament (5), Schillerndes Wasser (8), Makellose Protodrachenschuppe (10), Erweckte Ordnung (4)\nVerkäufer:\nScridorsa die Metzin\nZone:\nZaralekhöhle\nKosten:\n1\n\nSchlängelnder Kriecherdrache: Weißes Haar\nDrachenwächtermanuskript\nWird beim Aufheben gebunden\nBenutzen: Schaltet diese Anpassungsoption für den schlängelnden Kriecherdrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird.\n\"Eine Schriftrolle, die einen mächtigen Protodrachen mit leuchtend grünen Schuppen beschreibt.\"" }
