entries[408230] = { ["name"] = "Stockentenmörser", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHandvoll Serevitbolzen (60), Schockfederspule (6), Eingefettete Zahnräder (8), Bogenlichtkondensator (2), Verstärktes Maschinenchassis (2)\nVerkäufer:\nScrybbil\nZone:\nZaralekhöhle\nKosten:\n1\n\nStockentenmörser\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Schlägt einen Freund oder Gegner mit Eurer quietschigsten Gummiente auf den Kopf. (10 Min Abklingzeit)" }
entries[408231] = { ["name"] = "Bester-Brul-Faust", ["text"] = "Wirken in 2 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nDracothyst , Irdene Seele , Nozdorit (15), Glänzender Stein (200), Seidiger Juwelenstaub (150)\nVerkäufer:\nFanilly\nZone:\nZaralekhöhle\nKosten:\n1\n\nBester-Brul-Faust\nSpielzeug\nBenutzen: Gebt Euch mit Eurem besten Brul das Fäustchen! (1 Tag Abklingzeit)" }
entries[408232] = { ["name"] = "10GFX_VoidCosmic_Shader", ["text"] = "3% von Grundmana\nSofort 25 sek. Abklingzeit\nSchirmt Euch 1 Min. lang ab und absorbiert [0 + Frostzaubermacht * 10 * (1 + Vielseitigkeit)] Schaden . Nahkampfangriffe gegen Euch verringern die Bewegungsgeschwindigkeit des Angreifers um 50%." }
entries[408233] = { ["name"] = "Weyrnstein verschenken", ["text"] = "25 Meter ReichweiteWirken in 3 sek. 1 min Abklingzeit\nBeschwört zwei Weyrnsteine, einen für Euer verbündetes Ziel und einen für Euch selbst. Nur ein Verbündeter kann Euren Weyrnstein zur gleichen Zeit tragen.\n\nEin Weyrnstein kann von seinem Träger aktiviert werden, um ihn zum Ort des anderen Weyrnsteins zu teleportieren, wenn dieser sich in einem Umkreis von 100 Metern aufhält." }
entries[408234] = { ["name"] = "Weyrnstein aktivieren", ["text"] = "Wirken in 1.5 sek. 2 min Abklingzeit\nKonzentriert Euch für 1.5 Sek. auf den Stein, um Euch zu dem Träger des zugehörigen Weyrnsteins zu teleportieren, wenn dieser sich in einem Umkreis von 100 Metern aufhält." }
entries[408239] = { ["name"] = "Separationsschlag", ["text"] = "Unbegrenzte Reichweite\nSofort\nTyr schlägt mit überwältigender Kraft auf den Boden, verursacht 24244494 Arkanschaden, der innerhalb von 10 Metern gleichmäßig unter Spielercharakteren aufgeteilt wird, und hinterlässt ' Geweihter Boden '.\n\nFalls 'Separationsschlag' nicht mindestens zwei Spielercharaktere trifft, erhält Tyr ' Titanische Ermächtigung '." }
