entries[408578] = { ["name"] = "Ambossschlag", ["text"] = "100 Meter Reichweite\nSofort 1 min Abklingzeit\nSchlagt mit Eurer Waffe auf den Amboss, um sie zusätzlich zu verstärken. Fügt Gegnern in der Nähe 257 Schattenflammenschaden zu und erhöht den Trefferschaden bis kurz nach Verlassen des Kampfes um 33%. 5-mal stapelbar." }
