entries[408583] = { ["name"] = "Lavasturm", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 20 sek.)\nSchleudert Lava auf Gegner innerhalb von 50 Metern und fügt Gegnern innerhalb von 5 Metern um den Einschlagsort 50 Vulkanschaden zu.\n\nJeder Einschlag beschwört eine Lavakugel, die sich 6 Sek. lang auf einen Gegner fixiert und Gegnern innerhalb von 5 Metern 70 Vulkanschaden zufügt, wenn sie mit einem Gegner kollidiert." }
entries[408584] = { ["name"] = "Elementiumtaschenamboss", ["text"] = "8 Meter Reichweite\nSofort Ca. 2 Procs pro Minute\nSchärft Eure Waffe mit Elementium, was [der Hauptklassenfähigkeit Eurer Nahkampfschadensspezialisierung] eine Chance gewährt, bei Treffern zusätzlich ( 1346 * 0.6) Schattenflammenschaden zu verursachen.\n(100ms Abklingzeit)" }
