entries[408607] = { ["name"] = "Tiefenlichtglobus", ["text"] = "Ca. 1 Procs pro Minute\nEure Fähigkeiten haben eine Chance, den Globus zu entzünden, was Tiefenlichtmotten anlockt. Wenn Ihr eine angelockte Motte einsammelt, erhaltet Ihr 'Tiefenlichtharmonie', was Eure Hauptwert 10 Sek. lang um 219 erhöht." }
