entries[408627] = { ["name"] = "Feurige Schieferschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Man kann diese Kreatur leicht mit einem fliegenden, vulkanischen Stein verwechseln. Bis zu einem gewissen Grad stimmt das auch.\"\nVerkäufer:\nSaccratros\nZone:\nZaralekhöhle\nKosten:\n400" }
entries[408631] = { ["name"] = "Drachengeschmiedeter Magmaglücksbringer", ["text"] = "Ca. 1.5 Procs pro Minute\nEure Schaden verursachenden Fähigkeiten haben eine Chance, einen Magmawurm hervorzurufen, der eine geschmolzene Salve auf Euer Ziel entfesselt und bis zu ( 922 * 3) Feuerschaden verursacht." }
entries[408632] = { ["name"] = "Smaragdzurückhaltung", ["text"] = "2 Elan\nSofort 5 sek. Abklingzeit\nErhöht die Dauer von 'Winde des Lebens' um 5 Sek. Stellt nach 1 Sek. 1 Elan wieder her." }
