entries[408641] = { ["name"] = "Keimende Zwielichtglut", ["text"] = "Ca. 1.5 Procs pro Minute\nEure Fähigkeiten haben eine Chance, die Glut zu entzünden, was Euch im Verlauf von 10 Sek. 2334 Schattenflammenschaden zufügt und Euer Tempo um 228 erhöht." }
