entries[408644] = { ["name"] = "Keimende Zwielichtglut", ["text"] = "Ca. 2 Procs pro Minute\nBeim Erleiden von Schattenflammenschaden besteht eine Chance, dass Eure Geschwindigkeit 10 Sek. lang um 64 erhöht wird." }
entries[408645] = { ["name"] = "Der Schlichter", ["text"] = "Sofort\nSchaltet den Titel 'Schlichter/-in' für Eure Kriegsmeute frei." }
entries[408647] = { ["name"] = "Kobaltschieferschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Brut Karoktas, aufgewachsen im Tiefenlicht der Zaralekhöhle.\"\nBeute von:\nKarokta\nZone:\nZaralekhöhle" }
entries[408648] = { ["name"] = "Erwärmende Schieferschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Eine Schieferschwinge, die in Fyrakks Spur der Zerstörung geboren wurde. Verflucht von seiner Urflamme steigt seine Körpertemperatur langsam, aber stetig. Sie muss sich regelmäßig im Wasser abkühlen, um nicht von ihrer eigenen Hitze verzehrt zu werden.\"\nErfolg:\nQue Zara(lek), Zara(lek)\nKategorie:\nQuests" }
entries[408649] = { ["name"] = "Schattenflammenschieferschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ihr Panzer bestand ursprünglich aus dem geschmolzenen Magma, in dem sie geboren wurde, das dann zu dunklem Vulkangestein abkühlte. Die Macht der Schattenflamme machte ihn dann vollends unzerbrechlich.\"\nErfolg:\nRuhm des Aberrusschlachtzüglers" }
entries[408650] = { ["name"] = "Feurige Waffe" }
entries[408651] = { ["name"] = "Katalogisierte Schieferschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die erste entdeckte Art einer flammenden Schieferschwinge. Neun von zehn Wissenschaftlern sind sich einig: Er ist heiß!\"\nZone:\nZaralekhöhle\nÖffentliches Ereignis:\nForscher unter Feuer" }
entries[408652] = { ["name"] = "Schwelendes Heulen", ["text"] = "Sofort 1.5 min Abklingzeit\nRuft einen Hund herbei, der ein schwelendes Heulen ausstößt und Euren kritischen Trefferwert 20 Sek. lang um 205 erhöht." }
entries[408653] = { ["name"] = "Felsbrockenschlepper", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese Schieferschwingen wurden speziell darauf abgerichtet, große Mengen von Tauschfelsbrocken für die Feilscherei der Niffen zu tragen.\"\nVerkäufer:\nPonzo\nZone:\nZaralekhöhle\nKosten:\n85" }
entries[408654] = { ["name"] = "Sandige Schieferschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Muster auf den Schwingen dieser Kreatur ähneln Sand, der durch ein Stundenglas fließt. Man könnte sie ganze Zeitalter lang betrachten...\"\nVerkäufer:\nJeder Zeitwanderungshändler\nKosten:\n5.000" }
entries[408655] = { ["name"] = "Happenschnüffler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Eine Schieferschwingenart, die von den Niffen darauf abgerichtet wird, selbst die verstecktesten Happen zu finden.\"\nVerkäufer:\nHarlowe Marl\nZone:\nZaralekhöhle\nKosten:\n800" }
