entries[408659] = { ["name"] = "Eifernde Hinrichtung", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion verderbt den Glauben des Paladins, was ihn 30 Sek. lang dazu zwingt, alle 6 Sek. einen Hammer aus dem Licht zu rufen. Der Hammer weiht den Boden und fügt allen Zielen im Effektbereich 10 Heiligschaden zu. Zusätzlich erleiden sie 50 Heiligschaden, wenn der Hammer nach 5 Sek. landet." }
