entries[408661] = { ["name"] = "Vorwärtsbeschleunigung", ["text"] = "Kanalisiert (Wirken in 1 sek.)\nHebelt Reibung und Trägheit aus und legt einen neuen Kurs fest, unabhängig von Eurer aktuellen Geschwindigkeit.\n\nErmächtigung gewährt Euch einen Schub in eine neue Richtung. Je länger die Ermächtigung anhält, desto stärker der Schub." }
