entries[408760] = { ["name"] = "Blutroter Flug", ["text"] = "Sofort 30 sek. Abklingzeit\nStellt alle 1 Sek. 1 Elan wieder her. Gewährt bei der Wiederherstellung von Elan einen Vorwärtsschub, der die Geschwindigkeit erhöht. Kann nicht verwendet werden, wenn 'Rubinerschöpfung' aktiv ist." }
