entries[408762] = { ["name"] = "Erneuerung", ["text"] = "Sofort 10 sek. Abklingzeit\nSetzt die Abklingzeiten von 'Rubinerschöpfung' und 'Blutroter Flug' zurück. 'Blutroter Flug' muss dazu aktiv sein, und die verbleibende Dauer wird verbraucht." }
entries[408763] = { ["name"] = "Gebrochenes Eis", ["text"] = "100 Meter Reichweite\nSofort\nDer Schaden von 'Hagel' und 'Eislanze' ist um 20% erhöht. Euer Zauber 'Hagel' löst beim Einschlag eine Explosion aus, die Gegnern in der Nähe 35% seines Schadens zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
