entries[408783] = { ["name"] = "Zeitdruck", ["text"] = "Sofort\nWenn Ihr ein Ziel tötet, wird dessen Seele manchmal zerbrochen, wodurch für 20 Sek. ein Seelenfragment zurückbleibt.\n\nDas Seelenfragment wird aufgezehrt, wenn Ihr Euch nähert, und heilt Euch um (435.094% der Angriffskraft) Gesundheit.\n\nDas Aufzehren eines geringen Seelenfragments heilt Euch um 7% des in den letzten 5 Sek. erlittenen Schadens, mindestens jedoch um 1% Eurer maximalen Gesundheit.\n\nDas Aufzehren einer Dämonenseele gewährt Euch für 15 Sek. um 20% erhöhten Schaden.\n(15s Abklingzeit)" }
