entries[408927] = { ["name"] = "Zwillingsflammen", ["text"] = "Wirken in 1 sek.\nHüllt Gegner in ' Einäschernde Flammen ' oder ' Verderbte Flammen '.\n\nEinäschernde Flammen\nFügt Gegnern innerhalb von 10 Metern 14 Sek. lang alle 1 Sek. 271054 Feuerschaden zu.\n\nBetreten eines Bereichs von ' Verderbte Flammen ' entfernt diesen Effekt.\n\nBetreten eines Bereichs von ' Einäschernde Flammen ' eines anderen Spielercharakters löst eine heftige Explosion aus, die beiden Spielercharakteren 2710541 Feuerschaden zufügt.\n\nVerderbte Flammen\nFügt Gegnern innerhalb von 10 Metern 14 Sek. lang alle 1 Sek. 271054 Schattenflammenschaden zu.\n\nBetreten eines Bereichs von ' Einäschernde Flammen ' entfernt diesen Effekt.\n\nBetreten eines Bereichs von ' Verderbte Flammen ' eines anderen Spielercharakters löst eine heftige Explosion aus, die beiden Spielercharakteren 2710541 Schattenflammenschaden zufügt." }
entries[408929] = { ["name"] = "Verderbte Flammen", ["text"] = "100 Meter Reichweite\nSofort\nFügt Gegnern innerhalb von 10 Metern 14 Sek. lang alle 1 Sek. 271054 Schattenflammenschaden zu.\n\nBetreten eines Bereichs von ' Einäschernde Flammen ' entfernt diesen Effekt.\n\nBetreten eines Bereichs von ' Verderbte Flammen ' eines anderen Spielercharakters löst eine heftige Explosion aus, die beiden Spielercharakteren 2710541 Schattenflammenschaden zufügt." }
