entries[409385] = { ["name"] = "Schatten und Flamme", ["text"] = "Unbegrenzte Reichweite\nWirken in 4 sek.\nDie Schattenflammenverschmelzung markiert mehrere Spielercharaktere und versengt sie dann mit Schattenflamme, was Spielercharakteren innerhalb von 6 Metern um ihre Standorte 143252 Schattenflammenschaden zufügt.\n\nDie Hälfte der markierten Spielercharaktere wird mit ' Brennende Hitze ' belegt und die andere Hälfte mit ' Verderbender Schatten '. Diese Effekte nehmen alle 5 Sek. an Intensität zu." }
